// 1.1_PREP_Input — Parse, Validate, Filter, Build Template
// Replaces old 1.2_VAL_Input with v2 architecture:
//   1. Parse webhook body + handle camelCase keys from frontend
//   2. Guard: client_name required
//   3. Filter project_details to session-relevant fields
//   4. Extract pre-work metadata (competencies, themes) for KB search
//   5. Build deterministic slide template (17 types + Gagné + Kolb + AGES)

const body = $input.first().json.body || $input.first().json;

// ============================================================
// STEP 1: PARSE INPUTS (handle camelCase from frontend)
// ============================================================

function parseJSON(value, fieldName) {
  if (!value) return null;
  if (typeof value === 'object') return value;
  if (typeof value === 'string') {
    try { return JSON.parse(value); } catch (e) {
      return null;
    }
  }
  return null;
}

const projectDetails = parseJSON(body.project_details, 'project_details') || {};
const inputJson = parseJSON(body.input_json, 'input_json') || {};

// Handle camelCase keys from frontend
const preWorkSlides = inputJson.preWorkSummaryOutputJson
  || inputJson.pre_work_summary_output_json
  || {};

const sessionConstraints = inputJson.sessionConstraints
  || inputJson.session_constraints
  || {};

const contentOutlineUrl = inputJson.contentOutlineUrl
  || inputJson.content_outline_url
  || '';

// Fallback: if content_outline_url is empty, check documents_urls
const documentsUrls = body.documents_urls || '';

const clientName = body.client_name || '';

// ============================================================
// STEP 2: GUARD — client_name required
// ============================================================

if (!clientName) {
  return [{ json: {
    status: 'error',
    error_type: 'validation_error',
    error_message: 'Missing client_name'
  }}];
}

// ============================================================
// STEP 3: FILTER PROJECT_DETAILS
// ============================================================

const KEEP_FIELDS = [
  'name', 'industry', 'seniority_of_cohort', 'background',
  'client_objective', 'content_type', 'facilitators_name',
  'program_type', 'project_notes', 'project_components'
];

const filteredProjectDetails = {};
for (const field of KEEP_FIELDS) {
  if (projectDetails[field] !== undefined && projectDetails[field] !== null && projectDetails[field] !== '') {
    filteredProjectDetails[field] = projectDetails[field];
  }
}

// ============================================================
// STEP 4: EXTRACT PRE-WORK METADATA (for KB search in step 4)
// ============================================================

const competencies = [];
const developmentThemes = [];
const slideSummary = [];

const slideKeys = Object.keys(preWorkSlides).sort();
for (const key of slideKeys) {
  const slide = preWorkSlides[key];
  if (!slide || typeof slide !== 'object') continue;

  // Build slide summary (for step 5 tagging)
  slideSummary.push({
    id: key,
    slide_id: slide.slide_id || key,
    title: slide.slide_title || '',
    template_ref: String(slide.template_reference || ''),
    confidence: slide.confidence || '',
    size_chars: JSON.stringify(slide).length
  });

  const bullets = slide.bullets || {};

  // Extract competencies from slide_1_1 key_themes
  if (key === 'slide_1_1' && bullets.key_themes) {
    for (const theme of bullets.key_themes) {
      // Extract competency name (text before colon)
      const comp = theme.includes(':') ? theme.split(':')[0].trim() : theme.trim();
      if (comp) competencies.push(comp);
    }
  }

  // Extract development themes from slide_3_3 theme_N_name
  if (key === 'slide_3_3') {
    for (const [bk, bv] of Object.entries(bullets)) {
      if (bk.match(/^theme_\d+_name$/) && typeof bv === 'string') {
        developmentThemes.push(bv.trim());
      }
    }
  }

  // Extract behavioral themes from slide_3_2 section names
  if (key === 'slide_3_2') {
    for (const sectionName of Object.keys(bullets)) {
      // Convert section_name to readable: most_common_mentioned_... → "Most Common (70%+)"
      // Keep raw for now — LLM will interpret these
      if (sectionName && !competencies.includes(sectionName)) {
        // Don't add raw section names as competencies — they're frequency labels, not competency names
        // The actual competency names are in the bullet content, which the LLM will see
      }
    }
  }
}

const preWorkMetadata = {
  competencies,
  development_themes: developmentThemes,
  total_slides: slideKeys.length,
  slide_summary: slideSummary
};

// ============================================================
// STEP 5: BUILD DETERMINISTIC SLIDE TEMPLATE
// ============================================================

const slideTemplate = {
  slide_1:  { type: 'Session title',              gagne: 'Gain Attention',       kolb: null,  ages: 'Attention' },
  slide_2:  { type: 'Jombay intro',               gagne: null,                   kolb: null,  ages: 'Emotion' },
  slide_3:  { type: 'Trainer intro',              gagne: null,                   kolb: null,  ages: 'Emotion' },
  slide_4:  { type: 'Agenda',                     gagne: null,                   kolb: null,  ages: 'Attention' },
  slide_5:  { type: 'Working Agreement',          gagne: null,                   kolb: null,  ages: 'Generation' },
  slide_6:  { type: 'Program overview',           gagne: 'Stimulate Recall',     kolb: null,  ages: 'Attention' },
  slide_7:  { type: 'Objectives',                 gagne: 'Inform Objectives',    kolb: null,  ages: 'Attention' },
  slide_8:  { type: 'Module breaker',             gagne: null,                   kolb: null,  ages: 'Spacing' },
  slide_9:  { type: 'Content (AC)',               gagne: 'Present Content',      kolb: 'AC',  ages: 'Generation' },
  slide_10: { type: 'Quote',                      gagne: 'Provide Guidance',     kolb: null,  ages: 'Emotion' },
  slide_11: { type: 'Discussion/Reflection (RO)', gagne: 'Stimulate Recall',     kolb: 'RO',  ages: 'Generation' },
  slide_12: { type: 'Activity (CE)',              gagne: 'Elicit Performance',   kolb: 'CE',  ages: 'Generation' },
  slide_13: { type: 'Break',                      gagne: null,                   kolb: null,  ages: 'Spacing' },
  slide_14: { type: 'Questions',                  gagne: 'Provide Feedback',     kolb: null,  ages: 'Generation' },
  slide_15: { type: 'Feedback',                   gagne: 'Assess Performance',   kolb: null,  ages: 'Generation' },
  slide_16: { type: 'Call to Action (AE)',        gagne: 'Enhance Retention',    kolb: 'AE',  ages: 'Generation' },
  slide_17: { type: 'Closing',                    gagne: 'Enhance Retention',    kolb: null,  ages: 'Emotion' }
};

// ============================================================
// OUTPUT
// ============================================================

return [{ json: {
  status: 'validated',

  // Identity
  client_name: clientName,
  client_id: body.client_id || '',
  project_id: body.project_id || '',
  workflow_id: body.workflow_id || '',
  workflow_session_id: body.workflow_session_id || '',
  workflow_session_name: body.workflow_session_name || '',

  // Filtered project details
  project_details: filteredProjectDetails,

  // Pre-work: full slides (for step 5 distribution)
  pre_work_slides: preWorkSlides,

  // Extracted metadata (for step 4 KB search)
  pre_work_metadata: preWorkMetadata,

  // Session constraints
  session_constraints: sessionConstraints,

  // URLs
  content_outline_url: contentOutlineUrl || documentsUrls,
  documents_urls: documentsUrls,

  // Raw memory (for step 3 LLM filtering)
  current_project_memory: body.current_project_memory || '',

  // Sub-workflow IDs
  memory_id: body.memory_id || '',
  knowledge_base_id: body.knowledge_base_id || inputJson.knowledge_base_id || 'Q6OYS6AUC8',

  // Deterministic slide template
  slide_template: slideTemplate
}}];

// Format content outline URL for drive-utils extraction
// If URL is empty, drive-utils sub-workflow will fail and route via onError
const input = $('1.2_PREP_Input').first().json;
const url = input.content_outline_url || '';

return [{ json: {
  mode: 'EXTRACT_CONTENT',
  google_drive_file_url: url
}}];

// 4.1_JS_SplitGroups — v2: Targeted content distribution
// Key change: Uses content tags (step 5) to send ONLY relevant pre-work + KB per group.
// v1 sent ALL 73K chars of pre-work to ALL 7 groups (511K total).
// v2 sends each group only its tagged subset (est. 74K total).

const agent1 = $input.first().json.agent1_output;
const validatedInput = $('1.2_PREP_Input').first().json;
const tagData = $('2.10_JS_ParseTags').first().json;
const kbResults = $('2.7_JS_ParseKB').first().json.kb_results || [];

const blueprint = agent1.slide_blueprint || {};
const contentTags = tagData.content_tags || {};
const slideTemplate = validatedInput.slide_template || {};

// Full pre-work slides (keyed by slide_id like "slide_1_1", "slide_2_3", etc.)
const preWorkSlides = validatedInput.pre_work_slides || {};

// Index KB results by content_unit_id for O(1) lookup
const kbMap = {};
for (const unit of kbResults) {
  const id = unit.content_unit_id || unit.id;
  if (id) kbMap[id] = unit;
}

// Group definitions — same 7 groups as v1
const groupDefs = [
  { key: 'group_1', name: 'Title & Introduction', slides: ['slide_1','slide_2','slide_3'], types: 'Session title, Jombay intro, Trainer intro' },
  { key: 'group_2', name: 'Setup & Framing', slides: ['slide_4','slide_5'], types: 'Agenda, Working Agreement' },
  { key: 'group_3', name: 'Context & Objectives', slides: ['slide_6','slide_7'], types: 'Program overview, Objectives' },
  { key: 'group_4', name: 'Core Content', slides: ['slide_8','slide_9','slide_10'], types: 'Module breaker, Content (AC), Quote' },
  { key: 'group_5', name: 'Engagement & Application', slides: ['slide_11','slide_12'], types: 'Discussion/Reflection (RO), Activity (CE)' },
  { key: 'group_6', name: 'Transition & Reflection', slides: ['slide_13','slide_14','slide_15'], types: 'Break, Questions, Feedback' },
  { key: 'group_7', name: 'Action & Closing', slides: ['slide_16','slide_17'], types: 'Call to Action (AE), Closing' }
];

// Build per-group data with TARGETED content distribution
const groups = {};
for (const def of groupDefs) {
  // Blueprint entries for this group's slides
  const groupBlueprints = {};
  for (const slideKey of def.slides) {
    groupBlueprints[slideKey] = blueprint[slideKey] || {};
  }

  // Slide template entries (Gagné/Kolb/AGES — deterministic)
  const groupTemplate = {};
  for (const slideKey of def.slides) {
    groupTemplate[slideKey] = slideTemplate[slideKey] || {};
  }

  // Targeted pre-work: only slides tagged for this group's session slides
  const groupPreWork = {};
  const groupKB = [];
  const seenKB = {};

  for (const slideKey of def.slides) {
    const tags = contentTags[slideKey] || {};

    // Gather tagged pre-work slides (full content)
    for (const pwId of (tags.pre_work_slides || [])) {
      if (preWorkSlides[pwId] && !groupPreWork[pwId]) {
        groupPreWork[pwId] = preWorkSlides[pwId];
      }
    }

    // Gather tagged KB units (full content)
    for (const kbId of (tags.kb_units || [])) {
      if (kbMap[kbId] && !seenKB[kbId]) {
        groupKB.push(kbMap[kbId]);
        seenKB[kbId] = true;
      }
    }
  }

  groups[def.key] = {
    name: def.name,
    slides: def.slides,
    slide_types: def.types,
    blueprints: groupBlueprints,
    slide_template: groupTemplate,
    tagged_pre_work: groupPreWork,
    tagged_kb: groupKB
  };
}

// Common context (shared across all groups)
const commonContext = {
  session_overview: agent1.session_overview || {},
  mandatory_jombay_frameworks: agent1.mandatory_jombay_frameworks || [],
  sensitivity_log: agent1.sensitivity_log || []
};

// Agent 2 system prompt — v2: CONTENT ONLY (no facilitator scripts)
const agent2SystemPrompt = `ROLE: Expert content designer at Jombay (HR L&D consulting). Generate on-slide content for training session slides.

You receive: slide blueprints (strategic direction), slide template (Gagné/Kolb/AGES — FIXED), tagged pre-work data, tagged KB content units, client context.

YOUR JOB: Generate compelling, client-specific slide content for your assigned slides.

=== SLIDE TEMPLATE REFERENCE ===
Each slide has a fixed type with pre-assigned Gagné event, Kolb stage, and AGES function. These are provided in the slide_template — reference them but do NOT re-assign.

=== PRE-WORK DATA RULES ===
- bullets and slide_notes are PRIMARY content source — ground your content in these
- walkthrough_tip sets key message tone
- gaps/conflicts/ambiguity → MUST appear as reviewer_flags
- LOW confidence data → HEDGE the content, don't assert
- If no pre-work is tagged for your slides, use blueprint direction + KB content

=== ON-SLIDE CONTENT RULES ===
- LEAN and VISUAL-FIRST — slides are prompts, not scripts
- Headlines: punchy, memorable, client-specific (not generic)
- Subtext: one supporting line that adds context
- Bullets: max 4 per slide, each under 12 words
- Visual guidance: describe what visual/diagram/image to show
- NO speaker notes on participant slides

=== PROVENANCE RULE ===
For every slide, apply the 70% fit rule:
- >=70% fit with KB content → "Reused" with source reference
- 40-69% fit → "Adapted" with source and what needs changing
- <40% fit → "New" with rationale

=== QUALITY BAR ===
WISE (grounded in theory + context), WITTY (energy + personality), RELEVANT (client-specific)

=== OPERATING RULES ===
1. Follow the blueprint direction for each slide
2. Reference Gagné/Kolb/AGES from slide_template (they're fixed, not your decision)
3. Reuse Jombay KB content first (70% rule)
4. Flag pre-work gaps, conflicts, ambiguity — do NOT resolve them
5. Flag sensitivity concerns — do NOT ignore them
6. Activity slides: include step-by-step instructions + duration
7. Be concise — content goes ON slides, not in notes

=== OUTPUT SCHEMA ===
Return a JSON object with one key per slide:
{
  "slide_N": {
    "slide_title": "string",
    "headline": "punchy, memorable headline",
    "subtext": "supporting context line",
    "bullets": ["max 4 bullets", "each under 12 words"],
    "visual_guidance": "describe the visual element for this slide",
    "activity": {
      "has_activity": false,
      "instructions": null,
      "duration_minutes": null,
      "debrief_questions": []
    },
    "provenance": "New | Reused | Adapted",
    "provenance_source": "CU_id or null",
    "reviewer_flags": [{ "flag": "string", "reason": "string" }]
  }
}

IMPORTANT:
- Return one entry per assigned slide (use slide_1, slide_2, etc. as keys)
- Do NOT include facilitator scripts — those are generated separately
- Do NOT include modality notes — those are generated separately
- Activity slides (type 12) MUST have instructions and duration_minutes
- Every slide MUST have a headline and at least 1 bullet`;

return [{ json: {
  groups: groups,
  common_context: commonContext,
  client_context: {
    client_name: validatedInput.client_name,
    industry: validatedInput.project_details.industry || '',
    seniority_of_cohort: validatedInput.project_details.seniority_of_cohort || '',
    program_name: validatedInput.project_details.name || '',
    content_type: validatedInput.project_details.content_type || '',
    program_type: validatedInput.project_details.program_type || ''
  },
  session_constraints: validatedInput.session_constraints,
  agent2_system_prompt: agent2SystemPrompt,
  memory_id: validatedInput.memory_id,
  knowledge_base_id: validatedInput.knowledge_base_id,
  workflow_session_id: validatedInput.workflow_session_id,
  workflow_id: validatedInput.workflow_id,
  project_id: validatedInput.project_id,
  client_id: validatedInput.client_id
}}];

// 6.1_JS_Merge — v2: Merge 7 group content outputs + normalize to canonical schema
// Handles 2 LLM output formats:
//   A) { slide_1: { slide_title, headline, ... }, slide_2: { ... } }  — preferred
//   B) { slides: [ { slide_id, slide_title, ... } ] }  — array format
//
// Post-merge normalization ensures every slide has canonical keys regardless
// of which variant names the LLM used (title/headline/slide_title, etc.).

const items = $input.all();
const slideTemplate = $('1.2_PREP_Input').first().json.slide_template || {};

let mergedSlides = {};
let allGroupNotes = [];

function normalizeKey(id) {
  if (!id) return null;
  const s = String(id);
  return s.startsWith('slide_') ? s : 'slide_' + s;
}

// --- Extract flat bullets from various content structures ---
function extractBullets(slide) {
  if (Array.isArray(slide.bullets) && slide.bullets.length > 0) return slide.bullets;

  // content_blocks: array of objects or strings
  if (Array.isArray(slide.content_blocks)) {
    const bullets = [];
    for (const block of slide.content_blocks) {
      if (typeof block === 'string') {
        bullets.push(block);
      } else if (typeof block === 'object' && block !== null) {
        // Common sub-structures: { items: [...] }, { heading: "...", items: [...] }
        if (Array.isArray(block.items)) {
          for (const item of block.items) {
            bullets.push(typeof item === 'string' ? item : (item.text || item.point || JSON.stringify(item)));
          }
        } else if (Array.isArray(block.column_1_items)) {
          bullets.push(...block.column_1_items.filter(i => typeof i === 'string'));
        } else if (block.heading && !block.items) {
          bullets.push(block.heading);
        }
      }
    }
    return bullets.slice(0, 8);
  }

  // content / body_content / on_screen_text as string
  const textContent = slide.content || slide.body_content || slide.on_screen_text;
  if (typeof textContent === 'string' && textContent.length > 0) {
    return textContent.split(/\n/).map(s => s.replace(/^[\s•\-–—*]+/, '').trim()).filter(s => s.length > 3).slice(0, 8);
  }

  return [];
}

// --- Normalize reviewer_flags from various formats ---
function normalizeFlags(slide) {
  if (Array.isArray(slide.reviewer_flags) && slide.reviewer_flags.length > 0) return slide.reviewer_flags;

  const raw = slide.flags || slide.sensitivity_flags || [];
  if (!Array.isArray(raw)) return [];

  return raw.map(f => {
    if (typeof f === 'string') return { flag: f, reason: '' };
    if (typeof f === 'object' && f !== null) return { flag: f.flag || f.concern || f.issue || JSON.stringify(f), reason: f.reason || '' };
    return null;
  }).filter(Boolean);
}

// --- Normalize visual_guidance from various formats ---
function normalizeVisual(slide) {
  if (typeof slide.visual_guidance === 'string' && slide.visual_guidance) return slide.visual_guidance;
  if (typeof slide.visual_direction === 'string' && slide.visual_direction) return slide.visual_direction;
  if (typeof slide.visual_cues === 'string' && slide.visual_cues) return slide.visual_cues;
  if (Array.isArray(slide.visual_elements)) return slide.visual_elements.join('; ');
  if (typeof slide.visual_elements === 'string' && slide.visual_elements) return slide.visual_elements;
  if (Array.isArray(slide.visual_cues)) return slide.visual_cues.join('; ');
  return '';
}

// --- Merge groups ---

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  const response = data.llm_response || data;

  // Format A: slide_N as top-level keys (most common with v2 prompt)
  for (const [k, v] of Object.entries(response)) {
    if (/^slide_\d+$/.test(k) && typeof v === 'object' && v !== null) {
      mergedSlides[k] = v;
    }
  }

  // Format B: slides as array
  if (Array.isArray(response.slides)) {
    for (const slide of response.slides) {
      const key = normalizeKey(slide.slide_id || slide.slide_number);
      if (!key) continue;
      mergedSlides[key] = slide;
    }
  }

  // Legacy Format: slide_specs at top level (v1 compat)
  if (response.slide_specs && typeof response.slide_specs === 'object') {
    for (const [k, v] of Object.entries(response.slide_specs)) {
      const key = normalizeKey(k);
      if (key) mergedSlides[key] = v;
    }
  }

  // Group notes
  const notes = response.group_notes || response.group_summary;
  if (notes) allGroupNotes.push(typeof notes === 'string' ? notes : JSON.stringify(notes));
}

// --- Normalize each slide to canonical schema ---
// Canonical content keys: slide_number, slide_type, headline, subtext, bullets,
//   visual_guidance, key_message, activity, provenance, provenance_source, reviewer_flags
// Extra LLM fields (content_blocks, experience_anchors, etc.) are preserved as-is.

for (let i = 1; i <= 17; i++) {
  const key = `slide_${i}`;
  const slide = mergedSlides[key];

  if (!slide) {
    mergedSlides[key] = {
      slide_number: key,
      slide_type: (slideTemplate[key] || {}).type || '',
      headline: '', subtext: '', bullets: [],
      visual_guidance: '', key_message: '',
      activity: { has_activity: false, instructions: null, duration_minutes: null, debrief_questions: [] },
      provenance: 'New', provenance_source: '',
      reviewer_flags: [{ flag: 'MISSING', reason: 'No content generated for this slide' }]
    };
    continue;
  }

  // slide_number + slide_type (from template — authoritative source)
  slide.slide_number = key;
  slide.slide_type = (slideTemplate[key] || {}).type || slide.slide_type || slide.type || '';

  // headline: the primary display text for the slide
  if (!slide.headline) {
    slide.headline = slide.heading || slide.title || slide.slide_title || slide.quote_text || '';
  }
  // slide_title: descriptive title (may differ from headline)
  if (!slide.slide_title) {
    slide.slide_title = slide.heading || slide.title || slide.headline || '';
  }

  // subtext: supporting context line
  if (!slide.subtext) {
    slide.subtext = slide.subheading || slide.subheadline || slide.subtitle || slide.tagline || '';
  }

  // bullets: flat array of strings
  slide.bullets = extractBullets(slide);

  // visual_guidance: string description
  slide.visual_guidance = normalizeVisual(slide);

  // key_message: single string
  if (!slide.key_message) {
    if (Array.isArray(slide.key_messages)) {
      slide.key_message = slide.key_messages.join(' | ');
    } else {
      slide.key_message = '';
    }
  }

  // activity: object with canonical shape
  if (!slide.activity || typeof slide.activity !== 'object') {
    slide.activity = {
      has_activity: false,
      instructions: null,
      duration_minutes: slide.duration_minutes || null,
      debrief_questions: slide.debrief_questions || []
    };
  }

  // provenance + provenance_source
  // LLM sometimes returns provenance as an object — coerce to string
  if (typeof slide.provenance !== 'string') {
    if (typeof slide.provenance === 'object' && slide.provenance !== null) {
      slide.provenance = slide.provenance.status || slide.provenance.type || 'New';
    } else {
      slide.provenance = slide.provenance_notes ? 'Adapted' : 'New';
    }
  }
  if (!slide.provenance_source) {
    slide.provenance_source = (Array.isArray(slide.kb_units_referenced) && slide.kb_units_referenced.length > 0)
      ? slide.kb_units_referenced[0] : '';
  }

  // reviewer_flags: array of { flag, reason }
  slide.reviewer_flags = normalizeFlags(slide);
}

const filledCount = Object.values(mergedSlides).filter(s => s.headline || s.slide_title).length;

return [{ json: {
  status: filledCount >= 14 ? 'content_merged' : 'content_partial',
  slide_spec: mergedSlides,
  group_notes: allGroupNotes,
  total_slides: Object.keys(mergedSlides).length,
  filled_slides: filledCount
}}];

// 7.1_FMT_Agent3 — v2: QC Content Review (content-only, no facilitator scripts)
// v1 problem: 69K token prompt (slide_spec + facilitator_scripts + full pre-work + full agent1) → 300s TIMEOUT
// v2 fix: Content-only review (~8-11K tokens). Scripts reviewed separately after step 9.

const merged = $input.first().json;
const validatedInput = $('1.2_PREP_Input').first().json;
const agent1 = $('3.3_JS_ParseAgent1A').first().json.agent1_output;

const slideTemplate = validatedInput.slide_template || {};
const preWorkMeta = validatedInput.pre_work_metadata || {};

const systemPrompt = `ROLE: Senior COE Reviewer at Jombay (HR L&D consulting). You flag issues — you NEVER fix content.

You are reviewing SLIDE CONTENT ONLY (facilitator scripts are generated separately and reviewed later).

For every flag, provide:
1. What the issue is
2. Why it matters for the facilitator or learner
3. Direction for the fix (not the fix itself)

A slide that could belong to any client is a quality failure. Generic content is a flag, not a pass.

=== REVIEW CRITERIA ===

For EACH of the 17 slides, check:

A. STRUCTURAL COMPLETENESS
   - Has: slide_title, headline, subtext, bullets, visual_guidance
   - Activity slides: has_activity=true with instructions + duration

B. INSTRUCTIONAL ALIGNMENT
   - Slide type matches the blueprint intent
   - Gagné event honored (reference slide_template)
   - Kolb stage embedded where assigned (slides 9, 11, 12, 16)
   - AGES function applied

C. CONTENT QUALITY
   - Wise (grounded in theory + context), witty (energy), relevant (client-specific)
   - Bullets: max 4, each under 12 words
   - Headlines: punchy, not generic
   - Pre-work findings referenced where tagged

D. COMPLIANCE
   - No outcome guarantees
   - Sensitivity concerns flagged
   - Pre-work gaps/conflicts/ambiguity surfaced in reviewer_flags

E. PROVENANCE
