// Merge all 5 Agent 2 group outputs into unified slide_spec and facilitator_script
// Handles 3 LLM output formats:
//   A) { slide_specs: { slide_1: {...} }, facilitator_scripts: { slide_1: {...} } }
//   B) { slides: [ { slide_id, slide_spec, facilitator_script, ... } ] }
//   C) { slide_6: { slide_spec: {...}, facilitator_script: {...} }, slide_7: {...} }
const items = $input.all();

let mergedSlideSpecs = {};
let mergedFacilitatorScripts = {};
let allKBResults = [];
let allGroupNotes = [];

function normalizeKey(id) {
  if (!id) return null;
  const s = String(id);
  return s.startsWith('slide_') ? s : 'slide_' + s;
}

for (let i = 0; i < items.length; i++) {
  const data = items[i].json;
  const response = data.llm_response || data;

  // Format A: slide_specs and facilitator_scripts at top level
  if (response.slide_specs && typeof response.slide_specs === 'object') {
    Object.assign(mergedSlideSpecs, response.slide_specs);
  }
  if (response.facilitator_scripts && typeof response.facilitator_scripts === 'object') {
    Object.assign(mergedFacilitatorScripts, response.facilitator_scripts);
  }

  // Format B: slides as array
  if (Array.isArray(response.slides)) {
    for (const slide of response.slides) {
      const key = normalizeKey(slide.slide_id || slide.slide_number);
      if (!key) continue;
      if (slide.slide_spec) {
        mergedSlideSpecs[key] = slide.slide_spec;
      } else {
        const { facilitator_script, ...rest } = slide;
        mergedSlideSpecs[key] = rest;
      }
      if (slide.facilitator_script) {
        mergedFacilitatorScripts[key] = typeof slide.facilitator_script === 'string'
          ? { facilitator_script: slide.facilitator_script }
          : slide.facilitator_script;
      }
    }
  }

  // Format C: slide_N as top-level keys
  for (const [k, v] of Object.entries(response)) {
    if (/^slide_\d+$/.test(k) && typeof v === 'object' && v !== null) {
      if (v.slide_spec) {
        mergedSlideSpecs[k] = v.slide_spec;
      } else {
        const { facilitator_script, ...rest } = v;
        mergedSlideSpecs[k] = rest;
      }
      if (v.facilitator_script) {
        mergedFacilitatorScripts[k] = typeof v.facilitator_script === 'string'
          ? { facilitator_script: v.facilitator_script }
          : v.facilitator_script;
      }
    }
  }

  // Knowledge bank results (multiple possible keys)
  const kbr = response.knowledge_bank_search_results || response.knowledge_bank_results;
  if (Array.isArray(kbr)) allKBResults.push(...kbr);

  // Group notes (multiple possible keys)
  const notes = response.group_notes || response.group_summary;
  if (notes) allGroupNotes.push(typeof notes === 'string' ? notes : JSON.stringify(notes));
}

return [{ json: {
  slide_spec: mergedSlideSpecs,
  facilitator_script: mergedFacilitatorScripts,
  knowledge_bank_results: allKBResults,
  group_notes: allGroupNotes,
  total_slides: Object.keys(mergedSlideSpecs).length
}}];

// Assemble final output per Section 10 schema
const merged = $('6.1_JS_Merge').first().json;
const agent1 = $('3.8_JS_MergeAgent1B').first().json.agent1_output;
const agent3Response = $input.first().json;
const agent3 = agent3Response.llm_response || {};
const validatedInput = $('1.2_VAL_Input').first().json;

const slideSpec = merged.slide_spec || {};
const facilitatorScript = merged.facilitator_script || {};

// Embed Agent 3 flags into slide_spec reviewer_flags
for (const [slideId, review] of Object.entries(agent3.slide_reviews || {})) {
  const slideKey = 'slide_' + (review.slide_id || slideId.replace('slide_', ''));
  if (slideSpec[slideKey] && review.flags && review.flags.length > 0) {
    if (!slideSpec[slideKey].reviewer_flags) {
      slideSpec[slideKey].reviewer_flags = [];
    }
    slideSpec[slideKey].reviewer_flags.push(...review.flags);
  }
}

// Build provenance log
const provenanceLog = [];
for (const [slideId, slide] of Object.entries(slideSpec)) {
  provenanceLog.push({
    slide_id: slide.slide_id || slideId.replace('slide_', ''),
    slide_type: slide.slide_type || '',
    provenance: slide.provenance || 'New',
    source: slide.provenance_source || '',
    fit_percentage: slide.fit_percentage || 'N/A',
    rationale: slide.provenance_rationale || ''
  });
}

// Assemble final output
const finalOutput = {
  metadata: {
    project_name: validatedInput.project_details.project_name || '',
    client_name: validatedInput.client_name,
    session_type: validatedInput.session_constraints.session_type || '',
    total_duration: validatedInput.session_constraints.total_duration || '',
    total_slides: Object.keys(slideSpec).length,
    generated_date: new Date().toLocaleDateString('en-GB').replace(/\//g, '-'),
    overall_confidence: agent3.review_summary?.overall_quality || 'Medium',
    n8n_workflow_execution_id: $execution.id,
    n8n_workflow_execution_url: 'https://workflows.ur-nl.com/executions/' + $execution.id
  },
  session_overview: {
    workshop_title: agent1.session_overview?.workshop_title || agent1.session_overview?.session_title || agent1.session_overview?.title || validatedInput.workflow_session_name || '',
    key_themes: agent1.session_overview?.key_themes || agent1.session_overview?.themes || agent1.session_overview?.key_topics || agent1.key_design_decisions?.themes || [],
    learning_objectives: agent1.session_overview?.learning_objectives || agent1.session_overview?.objectives || agent1.session_overview?.learning_outcomes || [],
    audience_summary: agent1.session_overview?.audience_summary || agent1.session_overview?.facilitator_brief || agent1.session_overview?.target_audience || agent1.session_overview?.audience || '',
    gagne_map: {
      gain_attention: String(agent1.gagne_map?.gain_attention?.slide_numbers?.[0] || ''),
      inform_objectives: String(agent1.gagne_map?.inform_objectives?.slide_numbers?.[0] || ''),
      stimulate_recall: String(agent1.gagne_map?.stimulate_recall?.slide_numbers?.[0] || ''),
      present_content: String(agent1.gagne_map?.present_content?.slide_numbers?.[0] || ''),
      provide_guidance: String(agent1.gagne_map?.provide_guidance?.slide_numbers?.[0] || ''),
      elicit_performance: String(agent1.gagne_map?.elicit_performance?.slide_numbers?.[0] || ''),
      provide_feedback: String(agent1.gagne_map?.provide_feedback?.slide_numbers?.[0] || ''),
      assess_performance: String(agent1.gagne_map?.assess_performance?.slide_numbers?.[0] || ''),
      enhance_retention: String(agent1.gagne_map?.enhance_retention?.slide_numbers?.[0] || '')
    },
    kolb_map: {
      CE: String(agent1.kolb_map?.CE?.slide_number || '12'),
      RO: String(agent1.kolb_map?.RO?.slide_number || '11'),
      AC: String(agent1.kolb_map?.AC?.slide_number || '9'),
      AE: String(agent1.kolb_map?.AE?.slide_number || '16')
    }
  },
  slide_spec: slideSpec,
  facilitator_script: facilitatorScript,
  checklist_compliance_report: agent3.checklist_compliance_report || { overall_compliance: 'Medium', checklist_gaps: [] },
  reviewer_attention_log: agent3.reviewer_attention_log || { sensitivity_alerts: [], attention_items: [] },
  provenance_log: provenanceLog
};

return [{ json: {
  final_output: finalOutput,
  workflow_session_id: validatedInput.workflow_session_id
}}];

// ERROR FORMAT — Safely extract error info from any upstream node
const input = $input.first().json;
const webhookBody = $('1.1_TRG_Webhook').first().json.body || {};

return [{ json: {
  status: 'error',
  error_message: input.error_message || input.message || 'Workflow execution failed',
  error_type: input.error_type || 'execution_error',
  error_node: input.error_node || 'unknown',
  workflow_session_id: webhookBody.workflow_session_id || input.workflow_session_id || ''
}}];

// Parse Agent 1A output — normalize LLM response structure
// LLMs may wrap output in container keys and use alternative field names
const response = $input.first().json;

if (!response.llm_response || typeof response.llm_response !== 'object') {
  return [{ json: {
    status: 'error',
    error_type: 'agent1a_parse_error',
    error_message: 'Agent 1A did not return valid llm_response object',
    error_node: '3.3_JS_ParseAgent1A',
    workflow_session_id: $('1.2_VAL_Input').first().json.workflow_session_id
  }}];
}

let output = response.llm_response;

// Unwrap single container key (e.g. { strategic_instructional_framework: { ... } })
const topKeys = Object.keys(output);
if (topKeys.length === 1 && typeof output[topKeys[0]] === 'object' && !Array.isArray(output[topKeys[0]])) {
  output = output[topKeys[0]];
}

// ---- STEP 1: Map alternative top-level key names ----
const keyMap = {
  // session_overview alternatives
  session_metadata: 'session_overview',
  session_meta: 'session_overview',
  overview: 'session_overview',
  session_context: 'session_overview',
  // gagne_map alternatives
  gagne_events_mapping: 'gagne_map',
  gagne_mapping: 'gagne_map',
  gagne_events: 'gagne_map',
  gagne_nine_events_mapping: 'gagne_map',
  gagne_nine_events: 'gagne_map',
  gagne_framework: 'gagne_map',
  nine_events_of_instruction: 'gagne_map',
  // kolb_map alternatives
  kolb_mapping: 'kolb_map',
  kolb_cycle: 'kolb_map',
  kolb_experiential_learning: 'kolb_map',
  experiential_learning_cycle: 'kolb_map',
  // slide_blueprint alternatives (kept for compatibility)
  slides: 'slide_blueprint',
  slide_blueprints: 'slide_blueprint',
  slide_designs: 'slide_blueprint',
  // sensitivity_log alternatives
  unresolved_issues_register: 'sensitivity_log',
  unresolved_issues: 'sensitivity_log',
  sensitivity_alerts: 'sensitivity_log',
  unresolved_gaps_and_ambiguities: 'sensitivity_log',
  unresolved_flags: 'sensitivity_log',
  // competencies alternatives
  competencies: 'competencies_for_kb_search',
  kb_search_competencies: 'competencies_for_kb_search',
  knowledge_base_search: 'competencies_for_kb_search',
  // frameworks alternatives
  jombay_frameworks: 'mandatory_jombay_frameworks',
  frameworks: 'mandatory_jombay_frameworks',
  mandatory_frameworks: 'mandatory_jombay_frameworks'
};

const normalized = {};
for (const [key, value] of Object.entries(output)) {
  const mappedKey = keyMap[key] || key;
  normalized[mappedKey] = value;
}

// ---- STEP 2: Reconstruct session_overview from flat fields if missing ----
if (!normalized.session_overview || typeof normalized.session_overview !== 'object') {
  const so = {};
  // workshop_title
  so.workshop_title = normalized.session_title || normalized.workshop_title || normalized.title || '';
  // key_themes
  so.key_themes = normalized.key_themes || normalized.themes || normalized.core_themes || [];
  if (!Array.isArray(so.key_themes) && normalized.core_behavioral_shifts_targeted) {
    so.key_themes = normalized.core_behavioral_shifts_targeted;
  }
  if (!Array.isArray(so.key_themes) && normalized.session_focus) {
    so.key_themes = [normalized.session_focus];
  }
  // learning_objectives
  so.learning_objectives = normalized.learning_objectives || normalized.objectives || normalized.learning_outcomes || [];
  // audience_summary
  so.audience_summary = normalized.target_audience || normalized.audience_summary || normalized.audience || '';
  if (typeof so.audience_summary !== 'string') so.audience_summary = JSON.stringify(so.audience_summary);
  // session_arc_narrative
  so.session_arc_narrative = normalized.strategic_intent || normalized.session_arc_narrative || normalized.session_arc || normalized.session_narrative || '';

  // Only set if we found at least some content
  if (so.workshop_title || so.key_themes.length || so.audience_summary) {
    normalized.session_overview = so;
  }
}

// ---- STEP 3: Normalize session_overview inner structure ----
if (normalized.session_overview && typeof normalized.session_overview === 'object') {
  const so = normalized.session_overview;
  if (!so.workshop_title && so.title) so.workshop_title = so.title;
  if (!so.workshop_title && so.session_title) so.workshop_title = so.session_title;
  if (!so.key_themes && so.themes) so.key_themes = so.themes;
  if (!so.learning_objectives && so.objectives) so.learning_objectives = so.objectives;
  if (!so.audience_summary && so.audience) so.audience_summary = typeof so.audience === 'string' ? so.audience : JSON.stringify(so.audience);
  if (!so.audience_summary && so.target_audience) so.audience_summary = typeof so.target_audience === 'string' ? so.target_audience : JSON.stringify(so.target_audience);
}

// ---- STEP 4: Normalize gagne_map ----
if (normalized.gagne_map && typeof normalized.gagne_map === 'object') {
  const gm = normalized.gagne_map;
  const gagneKeyMap = {
    gaining_attention: 'gain_attention',
    informing_objectives: 'inform_objectives',
    stimulating_recall: 'stimulate_recall',
    presenting_content: 'present_content',
    providing_guidance: 'provide_guidance',
    eliciting_performance: 'elicit_performance',
    providing_feedback: 'provide_feedback',
    assessing_performance: 'assess_performance',
    enhancing_retention: 'enhance_retention'
  };
  for (const [altKey, stdKey] of Object.entries(gagneKeyMap)) {
    if (gm[altKey] && !gm[stdKey]) {
      gm[stdKey] = gm[altKey];
      delete gm[altKey];
    }
  }
  // Handle numbered/named event keys (event_1_gain_attention, event_2_inform_objectives, etc.)
  const numberedMap = [
    [/event.*1.*attention|gain.*attention/i, 'gain_attention'],
    [/event.*2.*objective|inform.*objective/i, 'inform_objectives'],
    [/event.*3.*recall|stimulat.*recall/i, 'stimulate_recall'],
    [/event.*4.*content|event.*4.*present|present.*content/i, 'present_content'],
    [/event.*5.*guid|event.*5.*learn|provide.*guid/i, 'provide_guidance'],
    [/event.*6.*practice|event.*6.*perform|elicit.*perform/i, 'elicit_performance'],
    [/event.*7.*feedback|provide.*feedback/i, 'provide_feedback'],
    [/event.*8.*assess/i, 'assess_performance'],
    [/event.*9.*retention|event.*9.*transfer|enhance.*retention/i, 'enhance_retention']
  ];
  for (const key of Object.keys(gm)) {
    for (const [pattern, stdKey] of numberedMap) {
      if (pattern.test(key) && !gm[stdKey]) {
        gm[stdKey] = gm[key];
        delete gm[key];
        break;
      }
    }
  }
  // Ensure each event has slide_numbers array and how string
  for (const [evtKey, val] of Object.entries(gm)) {
    if (typeof val === 'object' && val !== null) {
      if (!val.slide_numbers && val.slides) {
        val.slide_numbers = Array.isArray(val.slides) ? val.slides : [val.slides];
      }
      if (!val.slide_numbers && val.slide_number) {
        val.slide_numbers = Array.isArray(val.slide_number) ? val.slide_number : [val.slide_number];
      }
      if (!val.slide_numbers && val.primary_slides) {
        val.slide_numbers = Array.isArray(val.primary_slides) ? val.primary_slides : [val.primary_slides];
      }
      // If 'how' is missing but 'description' or 'strategy' exists
      if (!val.how && val.description) val.how = val.description;
      if (!val.how && val.strategy) val.how = val.strategy;
      if (!val.how && val.approach) val.how = val.approach;
      if (!val.how && val.implementation) val.how = val.implementation;
    }
    // If val is a string, wrap it
    if (typeof val === 'string') {
      normalized.gagne_map[evtKey] = { slide_numbers: [], how: val };
    }
  }
}

// ---- STEP 5: Extract kolb_map from key_instructional_decisions if missing ----
if (!normalized.kolb_map || typeof normalized.kolb_map !== 'object') {
  const kid = normalized.key_instructional_decisions || normalized.instructional_decisions || {};
  const km = {};

  // Try to extract kolb stages from key_instructional_decisions or from a kolb sub-object
  const kolbSrc = kid.kolb_cycle || kid.kolb_mapping || kid.kolb || kid;
  if (typeof kolbSrc === 'object') {
    const kolbKeyMap = {
      concrete_experience: 'CE', ce: 'CE',
      reflective_observation: 'RO', ro: 'RO',
      abstract_conceptualization: 'AC', abstract_conceptualisation: 'AC', ac: 'AC',
      active_experimentation: 'AE', ae: 'AE'
    };
    for (const [altKey, stdKey] of Object.entries(kolbKeyMap)) {
      if (kolbSrc[altKey] && !km[stdKey]) {
        km[stdKey] = kolbSrc[altKey];
      }
    }
  }

  // Default kolb mapping if nothing found
  if (!km.CE) km.CE = { slide_number: 12, concrete_experience: 'Activity/exercise slide' };
  if (!km.RO) km.RO = { slide_number: 11, reflection_focus: 'Discussion/reflection slide' };
  if (!km.AC) km.AC = { slide_number: 9, conceptual_model: 'Content/theory slide' };
  if (!km.AE) km.AE = { slide_number: 16, application_action: 'Call to action slide' };

  normalized.kolb_map = km;
} else {
  // Normalize existing kolb_map keys
  const km = normalized.kolb_map;
  const kolbKeyMap = {
    concrete_experience: 'CE',
    reflective_observation: 'RO',
    abstract_conceptualization: 'AC',
    abstract_conceptualisation: 'AC',
    active_experimentation: 'AE'
  };
  for (const [altKey, stdKey] of Object.entries(kolbKeyMap)) {
    if (km[altKey] && !km[stdKey]) {
      km[stdKey] = km[altKey];
      delete km[altKey];
    }
  }
}

// ---- STEP 6: Extract competencies from behavioral shifts if missing ----
if (!normalized.competencies_for_kb_search || !Array.isArray(normalized.competencies_for_kb_search)) {
  if (Array.isArray(normalized.core_behavioral_shifts_targeted)) {
    normalized.competencies_for_kb_search = normalized.core_behavioral_shifts_targeted.map(
      item => typeof item === 'string' ? item : (item.competency || item.name || item.shift || JSON.stringify(item))
    );
  } else {
    normalized.competencies_for_kb_search = [];
  }
}

// ---- STEP 7: Ensure mandatory_jombay_frameworks exists ----
if (!normalized.mandatory_jombay_frameworks) {
  normalized.mandatory_jombay_frameworks = [];
}

// ---- STEP 8: Normalize sensitivity_log to array ----
if (normalized.sensitivity_log && typeof normalized.sensitivity_log === 'object' && !Array.isArray(normalized.sensitivity_log)) {
  // Convert object-based sensitivity log to array
  const entries = [];
  for (const [category, items] of Object.entries(normalized.sensitivity_log)) {
    if (Array.isArray(items)) {
      for (const item of items) {
        entries.push(typeof item === 'string'
          ? { concern: item, recommendation: '', slide_number: '' }
          : item);
      }
    } else if (typeof items === 'string') {
      entries.push({ concern: items, recommendation: '', slide_number: '' });
    } else if (typeof items === 'object' && items !== null) {
      for (const [subKey, subItems] of Object.entries(items)) {
        if (Array.isArray(subItems)) {
          for (const si of subItems) {
            entries.push(typeof si === 'string'
              ? { concern: si, recommendation: '', slide_number: '' }
              : si);
          }
        }
      }
    }
  }
  normalized.sensitivity_log = entries;
}
if (!normalized.sensitivity_log) {
  normalized.sensitivity_log = [];
}

// ---- STEP 9: Normalize slide_blueprint if present ----
if (Array.isArray(normalized.slide_blueprint)) {
  const keyed = {};
  for (const slide of normalized.slide_blueprint) {
    const id = slide.slide_id || slide.slide_number;
    const key = id ? (String(id).startsWith('slide_') ? String(id) : 'slide_' + id) : 'slide_' + (Object.keys(keyed).length + 1);
    keyed[key] = slide;
  }
  normalized.slide_blueprint = keyed;
}

return [{ json: {
  status: 'agent1a_parsed',
  agent1a_output: normalized
}}];

// Merge 5 Agent 1B blueprint outputs into unified agent1_output
const agent1a = $('3.3_JS_ParseAgent1A').first().json.agent1a_output;
const items = $input.all();

let mergedBlueprint = {};

for (const item of items) {
  const response = item.json;
  let output = response.llm_response || response;

  // Unwrap single container key
  const topKeys = Object.keys(output);
  if (topKeys.length === 1 && typeof output[topKeys[0]] === 'object' && !Array.isArray(output[topKeys[0]])) {
    output = output[topKeys[0]];
  }

  // Extract slide_blueprint
  let bp = output.slide_blueprint || output.slide_blueprints || output.slides || {};

  // If array, convert to keyed object
  if (Array.isArray(bp)) {
    const keyed = {};
    for (const slide of bp) {
      const id = slide.slide_id || slide.slide_number;
      const key = id ? (String(id).startsWith('slide_') ? String(id) : 'slide_' + id) : 'slide_' + (Object.keys(keyed).length + 1);
      keyed[key] = slide;
    }
    bp = keyed;
  }

  // Check for slide_N keys at top level
  for (const [k, v] of Object.entries(output)) {
    if (/^slide_\d+$/.test(k) && typeof v === 'object' && v !== null && !bp[k]) {
      bp[k] = v;
    }
  }

  Object.assign(mergedBlueprint, bp);
}

const agent1Output = {
  session_overview: agent1a.session_overview || {},
  gagne_map: agent1a.gagne_map || {},
  kolb_map: agent1a.kolb_map || {},
  slide_blueprint: mergedBlueprint,
  mandatory_jombay_frameworks: agent1a.mandatory_jombay_frameworks || [],
  competencies_for_kb_search: agent1a.competencies_for_kb_search || [],
  sensitivity_log: agent1a.sensitivity_log || []
};

return [{ json: {
  status: 'agent1_parsed',
  agent1_output: agent1Output
}}];

// Format KB search prompt using pre-work competencies + client context
const validatedInput = $('1.2_VAL_Input').first().json;
const preWork = validatedInput.pre_work_summary || {};
const projectDetails = validatedInput.project_details || {};
const sessionConstraints = validatedInput.session_constraints || {};

// Extract competencies/themes from pre-work metadata
const metadata = preWork.metadata || {};
const competencies = metadata.competencies || metadata.key_competencies || [];
const themes = metadata.themes || metadata.key_themes || [];
const behavioralFocus = metadata.behavioral_focus_areas || metadata.focus_areas || [];

const competencyList = [
  ...(Array.isArray(competencies) ? competencies : [competencies]),
  ...(Array.isArray(themes) ? themes : [themes]),
  ...(Array.isArray(behavioralFocus) ? behavioralFocus : [behavioralFocus])
].filter(Boolean).join(', ');

const systemPrompt = 'You are a knowledge base search specialist at Jombay. Your job is to search the ' +
  'knowledge base for ALL relevant frameworks, models, assessments, content summaries, ' +
  'and reusable content units. Search broadly \u2014 the results will be used by downstream ' +
  'agents to generate slide content and facilitator scripts aligned with Jombay IP.\n\n' +
  'Return all search results as-is in a JSON array. Include content summaries, titles, ' +
  'content unit IDs, and any metadata. Do NOT filter or summarize \u2014 return everything.';

const userPrompt = 'Search the knowledge base for Jombay content relevant to this training session:\n\n' +
  '=== SESSION CONTEXT ===\n' +
  'Client: ' + validatedInput.client_name + '\n' +
  'Industry: ' + (projectDetails.industry || 'Not specified') + '\n' +
  'Audience level: ' + (projectDetails.seniority || 'Not specified') + '\n' +
  'Session topic: ' + (projectDetails.project_name || sessionConstraints.session_type || 'Not specified') + '\n\n' +
  '=== COMPETENCIES & THEMES ===\n' +
  (competencyList || 'No specific competencies extracted from pre-work') + '\n\n' +
  '=== INSTRUCTIONS ===\n' +
  '1. Call search_knowledge_base with competencies and audience context\n' +
  '2. Search for frameworks, models, assessment tools, and content summaries\n' +
  '3. Return ALL results \u2014 include content summaries so downstream agents can use them directly when generating slide content\n' +
  '4. Do NOT skip any result \u2014 err on the side of returning more content';

return [{ json: {
  system_prompt: systemPrompt,
  prompt: userPrompt,
  model: 'global.anthropic.claude-haiku-4-5-20251001-v1:0',
  node_name: 'KBPreFetch',
  memory_id: validatedInput.memory_id,
  knowledge_base_id: validatedInput.knowledge_base_id,
  workflow_session_id: validatedInput.workflow_session_id,
  workflow_id: validatedInput.workflow_id,
  project_id: validatedInput.project_id,
  client_id: validatedInput.client_id
}}];

// Parse KB search results from LLM response
const response = $input.first().json;
const llmResponse = response.llm_response || response;

let kbResults = [];

// Extract KB results from various possible response formats
if (Array.isArray(llmResponse)) {
  kbResults = llmResponse;
} else if (typeof llmResponse === 'object') {
  kbResults = llmResponse.search_results
    || llmResponse.knowledge_base_results
    || llmResponse.results
    || llmResponse.content_units
    || llmResponse.kb_results
    || [];

  if (kbResults.length === 0 && llmResponse.data) {
    kbResults = Array.isArray(llmResponse.data) ? llmResponse.data : [llmResponse.data];
  }
}

// Ensure it's always an array
if (!Array.isArray(kbResults)) {
  kbResults = [kbResults];
}

// Filter: strip s3_location and result_index, limit to top 10 by relevance
kbResults = kbResults.slice(0, 10).map(r => {
  const { s3_location, result_index, ...rest } = r;
  return rest;
});

return [{ json: {
  status: 'kb_fetched',
  kb_results: kbResults,
  kb_result_count: kbResults.length
}}];
